import{_ as e,o as l,c as a,a0 as n}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"展开链讲稿 · 第一分册：从问题到链条","description":"","frontmatter":{},"headers":[],"relativePath":"L001_第一分册_从问题到链条.md","filePath":"L001_第一分册_从问题到链条.md"}'),d={name:"L001_第一分册_从问题到链条.md"};function r(o,t,s,i,g,$){return l(),a("div",null,[...t[0]||(t[0]=[n('<div><h1 id="展开链讲稿-·-第一分册-从问题到链条" tabindex="-1">展开链讲稿 · 第一分册：从问题到链条 <a class="header-anchor" href="#展开链讲稿-·-第一分册-从问题到链条" aria-label="Permalink to &quot;展开链讲稿 · 第一分册：从问题到链条&quot;">​</a></h1><blockquote><p><strong>稿子性质</strong>：本稿是<strong>撰写</strong>，不是摘录。它的职责是把散在 <code>01</code>–<code>07</code> 各分册里的推理顺序重新铺成一条能读下去的线： 先说清问题（为什么非要换一个量子化对象），再给出最小内核，然后一层层展开到规范群、量纲、两种引力，最后把<strong>未闭合的地方留在链条上</strong>。</p><p><strong>它不是权威源</strong>。权威源仍是各文档原文与根 <code>README.md</code>；本稿的每一条论断都在<strong>附录 A</strong> 里钉到出处， 凡本次未逐字核对到原文的，在附录 A 里如实标为「待逐字核对」。</p><p><strong>三条写作纪律</strong>（本稿对 <code>AGENTS.md</code> 三条红线的具体执行）：</p><ol><li><strong>不欺骗</strong>——未证处不得写成已证。本稿凡涉及未闭合处，一律写明缺口编号与状态。</li><li><strong>不绕过</strong>——缺口不省略、不用&quot;因此&quot;跨过；必须跨时，句式是&quot;在缺口 X 未闭合的前提下，下游成立的是……&quot;。</li><li><strong>不虚构</strong>——只用原文已有的概念、术语、数值与关系；不引入原文未涉及的观点，也不替原文补理由（原文未展开动机处，本稿明写&quot;原文未在此处展开&quot;）。</li></ol></blockquote><hr><h2 id="卷首-·-怎么读这份稿子" tabindex="-1">卷首 · 怎么读这份稿子 <a class="header-anchor" href="#卷首-·-怎么读这份稿子" aria-label="Permalink to &quot;卷首 · 怎么读这份稿子&quot;">​</a></h2><p>同一条链，可以站在四个高度上看。高度不是&quot;难度&quot;，是&quot;省略了什么&quot;：</p><table tabindex="0"><thead><tr><th style="text-align:left;">层</th><th style="text-align:left;">省略什么</th><th style="text-align:left;">回答什么</th><th style="text-align:left;">在哪节</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>导读层</strong></td><td style="text-align:left;">省略全部公式与构造细节</td><td style="text-align:left;">这件事到底在解决什么问题</td><td style="text-align:left;">第一章</td></tr><tr><td style="text-align:left;"><strong>概念层</strong></td><td style="text-align:left;">省略推导，保留定义与对象</td><td style="text-align:left;">换的是什么对象，凭什么可以换</td><td style="text-align:left;">第二章</td></tr><tr><td style="text-align:left;"><strong>链条层</strong></td><td style="text-align:left;">不省略顺序，标注每一步的本体论状态与断点</td><td style="text-align:left;">从物质到规范群，中间经过了哪几步</td><td style="text-align:left;">第三章、第五章</td></tr><tr><td style="text-align:left;"><strong>技术层</strong></td><td style="text-align:left;">不省略任何东西</td><td style="text-align:left;">严格表述、证明与形式化</td><td style="text-align:left;">指向原文对应章节（见附录 A）</td></tr></tbody></table><p>层与层之间是<strong>同一条链的四个投影</strong>，不是四份不同的说法——所以不必担心&quot;浅层读法&quot;和&quot;深层读法&quot;打架：它们共用同一批论断、同一批锚点。真正的理解发生在<strong>层与层之间的往返</strong>上：往上走看清模式，往下走看清原因。</p><p><strong>锚点约定</strong>：正文里的 <code>【锚 A-xx】</code> 指向附录 A 的锚点表（出处文档 + 章节定位 + 本次核对状态）。</p><hr><h2 id="第一章-问题-该量子化什么-导读层" tabindex="-1">第一章 问题：该量子化什么（导读层） <a class="header-anchor" href="#第一章-问题-该量子化什么-导读层" aria-label="Permalink to &quot;第一章 问题：该量子化什么（导读层）&quot;">​</a></h2><p>现代物理学的三条主要进路，各自都做了同一类选择——<strong>挑一个对象，把它量子化</strong>。而这个选择，恰好是它们各自困难的来源：</p><ul><li><strong>因果集</strong>量子化时空的因果结构，但没有动力学方程；</li><li><strong>关系量子力学</strong>量子化观察关系，代价是取消了物自体，从而滑向结构性唯心主义；</li><li><strong>圈量子引力</strong>量子化位置空间的度规，但难以恢复低能物理与标准模型参数。</li></ul><p>三条路的困难并不相同，却指向同一个未回答的问题：<strong>应该量子化什么？</strong>【锚 A-01】</p><p>CQM 的回答是：<strong>量子化的对象是耦合常数本身</strong>。时空与标准模型都不是前提，而是耦合常数量子力学在<strong>禁闭边界</strong>上的涌现。【锚 A-01】</p><p>这个转向立刻带来一个本体论上的重新排序：<strong>物质是先在的</strong>。它不需要一个&quot;从虚无中创生&quot;的起点，也不需要一张预先铺好的时空舞台；质子与中子作为<strong>有限本体</strong>，通过再生产操作维持自身存在——<strong>存在先于过程，过程维持存在</strong>。【锚 A-02】【锚 A-03】</p><p>顺带把一处容易混的地方定下来：在这个框架里，<strong>自组织</strong>是最一般的范畴（物质自发组织出结构），而<strong>退相干是其中一类自组织的表现</strong>。引力（因果限制场）提供退相干得以发生的因果结构，但退相干并不等于只由引力承担。【锚 A-04】</p><p>问题交代完了。接下来的全部内容，都只是在回答一件事：换了量子化对象之后，<strong>那些常数和对称性从哪里长出来</strong>。</p><hr><h2 id="第二章-最小内核-一个替换-概念层" tabindex="-1">第二章 最小内核：一个替换（概念层） <a class="header-anchor" href="#第二章-最小内核-一个替换-概念层" aria-label="Permalink to &quot;第二章 最小内核：一个替换（概念层）&quot;">​</a></h2><h3 id="_2-1-为什么不直接用耦合强度-r" tabindex="-1">2.1 为什么不直接用耦合强度 $r$ <a class="header-anchor" href="#_2-1-为什么不直接用耦合强度-r" aria-label="Permalink to &quot;2.1 为什么不直接用耦合强度 $r$&quot;">​</a></h3><p>要让&quot;耦合常数&quot;成为一个量子力学量，最直觉的做法是把它当坐标。但直接用 $r$ 走不通：$r$ 的值域是 $(0,\\infty)$ 而不是全实轴 $\\mathbb{R}$，而且对易子里会含 $r$ 本身，算符理论立即变难。【锚 A-05】</p><h3 id="_2-2-取对数之后-一切都变成标准的" tabindex="-1">2.2 取对数之后，一切都变成标准的 <a class="header-anchor" href="#_2-2-取对数之后-一切都变成标准的" aria-label="Permalink to &quot;2.2 取对数之后，一切都变成标准的&quot;">​</a></h3><p>取 $u=\\ln r$ 之后，三件事同时到位：</p><ul><li>值域变成 $\\mathbb{R}$，与标准量子力学一致；</li><li>对易子变成 $[\\hat u,\\hat p_u]=i$——一个<strong>无量纲</strong>的标准海森堡代数；</li><li>于是标准量子力学的整套谱理论（自伴扩张、不确定性、谱分解）可以直接调用。【锚 A-05】</li></ul><p>这不是为了好看。原文给的理由是物理的：耦合常数的<strong>跑动</strong>在标准场论中本来就是<strong>对数跑动</strong>（$g^2\\sim 1/\\ln\\mu$），在 CQM 中它对应传输方程特征线的有理函数解 $r(\\tau)=1/(-v\\tau+C)$；取 $u=\\ln r$ 正是把 RG 流的二次非线性跑动，改写成耦合空间里的几何描述。【锚 A-05】</p><h3 id="_2-3-舞台不是凭空设的-sprinkling-测度" tabindex="-1">2.3 舞台不是凭空设的：Sprinkling 测度 <a class="header-anchor" href="#_2-3-舞台不是凭空设的-sprinkling-测度" aria-label="Permalink to &quot;2.3 舞台不是凭空设的：Sprinkling 测度&quot;">​</a></h3><p>把 $u$ 当坐标，就得交代<strong>测度</strong>从哪来。答案是它来自因果集本身：</p><blockquote><p><strong>定理 4.1（Sprinkling 测度）</strong>：$v$ 坐标中的均匀 Sprinkling 严格导出 $u$ 坐标中的测度 $d\\mu=e^{-u}du$。</p></blockquote><p>证明只有两行：Sprinkling 在 $v$ 坐标中均匀即 $d\\mu_{\\text{spr}}=\\rho,dv$；由 $v=e^{-u}$ 得 $dv=-e^{-u}du$，吸收常数后即得 $d\\mu=e^{-u}du$。【锚 A-10】</p><p>于是希尔伯特空间被<strong>逼</strong>出来，而不是被选出来：</p><p>$$\\mathcal H=L^2(\\mathbb R,,e^{-u}du),\\qquad \\langle f,g\\rangle=\\int f^*(u)g(u)e^{-u}du .$$</p><p>原文对这一点的用词很重：这是因果集 Sprinkling 在耦合坐标下的<strong>严格几何效应</strong>。【锚 A-10】</p><h3 id="_2-4-与传统量子力学的对照" tabindex="-1">2.4 与传统量子力学的对照 <a class="header-anchor" href="#_2-4-与传统量子力学的对照" aria-label="Permalink to &quot;2.4 与传统量子力学的对照&quot;">​</a></h3><p>把两边并排放，替换的幅度一目了然：</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">传统量子力学</th><th style="text-align:left;">CQM</th></tr></thead><tbody><tr><td style="text-align:left;">坐标</td><td style="text-align:left;">$\\hat x$</td><td style="text-align:left;">$\\hat u=\\ln\\hat r$（对数耦合常数）</td></tr><tr><td style="text-align:left;">动量</td><td style="text-align:left;">$\\hat p=-i\\hbar,\\partial_x$</td><td style="text-align:left;">$\\hat p_u=-i,\\partial_u$（固有时流速共轭动量，$\\hat p_u=\\hat v_\\tau/☯$）</td></tr><tr><td style="text-align:left;">对易子</td><td style="text-align:left;">$[\\hat x,\\hat p]=i\\hbar$</td><td style="text-align:left;">$[\\hat u,\\hat p_u]=i$</td></tr><tr><td style="text-align:left;">希尔伯特空间</td><td style="text-align:left;">$L^2(\\mathbb R,dx)$</td><td style="text-align:left;">$L^2(\\mathbb R,e^{-u}du)$</td></tr><tr><td style="text-align:left;">测度</td><td style="text-align:left;">均匀 $dx$</td><td style="text-align:left;">指数加权 $e^{-u}du$（来自 Sprinkling）</td></tr><tr><td style="text-align:left;">作用量量子</td><td style="text-align:left;">$\\hbar$</td><td style="text-align:left;">$☯=\\frac{d}{ds}\\ln\\xi(s)\\big</td></tr></tbody></table><p>原文强调：<strong>这不是类比，而是严格的数学同构</strong>——两套量子力学共享同一个代数结构，只是舞台不同。【锚 A-06】【锚 A-11】</p><h3 id="_2-5-☯-是从哪来的" tabindex="-1">2.5 $☯$ 是从哪来的 <a class="header-anchor" href="#_2-5-☯-是从哪来的" aria-label="Permalink to &quot;2.5 $☯$ 是从哪来的&quot;">​</a></h3><p>上表最后一行的 $☯$ 需要单独交代，因为它不是假设出来的量子，而是从黎曼 $\\xi$ 函数<strong>算出来</strong>的：</p><p>$$☯=\\frac{d}{ds}\\ln\\xi(s)\\Big|_{s=1}=\\frac{\\xi&#39;(1)}{\\xi(1)}=1+\\frac{\\gamma}{2}-\\ln(2\\sqrt\\pi)\\approx 0.023095708966 .$$</p><p>原文说明它由 $\\xi(s)=\\xi(1-s)$ 的函数方程与 $\\psi(1/2)=-\\gamma-2\\ln 2$ <strong>严格推出</strong>，解析值与数值微分互验，精确到 $10^{-7}$。【锚 A-07】</p><p>这里有两层必须分开写，因为它们的严格性不同：</p><ul><li><strong>Hadamard 恒等式</strong>（<strong>不依赖 RH</strong>）：$☯=\\sum_{\\rho}\\frac{1}{1-\\rho}$，$\\rho$ 遍历全部黎曼零点；</li><li><strong>谱表示</strong>（<strong>条件于 RH</strong>）：若零点都在临界线上（$\\rho=\\tfrac12+i\\gamma_n$），则配对后得 $☯=\\sum_{n=1}^{\\infty}\\frac{1}{\\gamma_n^2+1/4}$。【锚 A-08】</li></ul><p>也就是说：$☯$ 的<strong>数值</strong>不依赖 RH，但它在临界线上&quot;是全部零点按 $1/(\\gamma_n^2+1/4)$ 加权的集体贡献&quot;这一读法，条件于 RH。写作时这一层不能糊：任何&quot;$☯$ 就是零点谱权重和&quot;的说法都必须带上条件。</p><p>还有一个被原文专门解释过的选择：<strong>为什么取 $\\xi$ 而不取 $\\zeta$</strong>。因为 $\\xi$ 的零点集恰好是非平凡零点 ${\\gamma_n}$——$\\Gamma(s/2)$ 的极点正好抵消 $\\zeta$ 的平凡零点 $(-2,-4,\\dots)$；而 $\\zeta$ 在 $s=1$ 有极点，$\\frac{d}{ds}\\ln\\zeta(s)|_{s=1}$ 直接发散。两者的分工是：$\\zeta$ 是同一个 $\\mathrm{GL}(1)$ $L$ 函数的<strong>算术面孔</strong>（Euler 积、有极点），$\\xi$ 是<strong>谱面孔</strong>（整函数、只含非平凡零点）。$☯$ 取自谱面孔。【锚 A-09】</p><h3 id="_2-6-不确定性的物理读法" tabindex="-1">2.6 不确定性的物理读法 <a class="header-anchor" href="#_2-6-不确定性的物理读法" aria-label="Permalink to &quot;2.6 不确定性的物理读法&quot;">​</a></h3><p>有了 $[\\hat u,\\hat p_u]=i$，不确定性关系就是 $\\Delta u\\cdot\\Delta p_u\\ge\\frac12$；换成相对耦合不确定度，写成</p><p>$$\\frac{\\Delta r}{\\langle r\\rangle}\\cdot\\Delta v_\\tau\\ \\ge\\ \\frac{☯}{2}.$$</p><p>原文给的物理诠释是：在单个质子内部，<strong>耦合常数的相对不确定度与固有时流速的不确定度互斥</strong>——越精确地测定这个系统的耦合常数，就越无法精确测定它的固有时此刻流得多快。【锚 A-06】</p><p>至此最小内核完整：一个替换、一个由 Sprinkling 逼出的测度、一个从 $\\xi$ 算出的作用量量子。<strong>后面的一切都是它的展开</strong>。</p><hr><h2 id="第三章-六步链条-从物质到规范群-链条层" tabindex="-1">第三章 六步链条：从物质到规范群（链条层） <a class="header-anchor" href="#第三章-六步链条-从物质到规范群-链条层" aria-label="Permalink to &quot;第三章 六步链条：从物质到规范群（链条层）&quot;">​</a></h2><p>原文把本体论骨架压缩成一条六步链条，并<strong>给每一步标注了本体论状态</strong>。下面逐步撰写；每步末尾若触及未闭合处，就地标出断点，不推迟到章末。</p><p>$$\\text{物质（先在）}\\to\\text{用质数自组织}\\to\\text{GL(5) 潜能先在}\\to\\text{自组织成 SU(5) 基态}\\to\\text{p 进大小耦合分化／重组实现}\\to U(1)\\times SU(2)\\times SU(3)$$</p><h3 id="第一步-·-物质-先在-不可创生" tabindex="-1">第一步 · 物质：先在，不可创生 <a class="header-anchor" href="#第一步-·-物质-先在-不可创生" aria-label="Permalink to &quot;第一步 · 物质：先在，不可创生&quot;">​</a></h3><p>链条的起点不是方程，而是一个存在论判断：物质先在。它在链条里的状态是 <strong><code>L0</code> 公理</strong>——即整个体系的前提，不由链条中的其他步骤推出。【锚 A-12】</p><h3 id="第二步-·-用质数自组织-前时空" tabindex="-1">第二步 · 用质数自组织：前时空 <a class="header-anchor" href="#第二步-·-用质数自组织-前时空" aria-label="Permalink to &quot;第二步 · 用质数自组织：前时空&quot;">​</a></h3><p>物质自组织的最原始生成元是<strong>质数</strong>。这一步的本体论状态是<strong>前时空</strong>：没有时空、没有规范群，物质处于前时空的状态。【锚 A-12】【锚 A-15】</p><h3 id="第三步-·-gl-5-潜能先在-算术潜能" tabindex="-1">第三步 · GL(5) 潜能先在：算术潜能 <a class="header-anchor" href="#第三步-·-gl-5-潜能先在-算术潜能" aria-label="Permalink to &quot;第三步 · GL(5) 潜能先在：算术潜能&quot;">​</a></h3><p>关键的一步在这里，也是全链条的&quot;灵魂&quot;：<strong>伽罗瓦表示结构作为可能性，先于物理存在</strong>。它的状态是<strong>算术潜能</strong>——物质用质数自组织时，GL(5) 的可能性已经内禀地存在了。【锚 A-12】【锚 A-13】</p><h3 id="第四步-·-自组织成-su-5-基态-基态同步" tabindex="-1">第四步 · 自组织成 SU(5) 基态：基态同步 <a class="header-anchor" href="#第四步-·-自组织成-su-5-基态-基态同步" aria-label="Permalink to &quot;第四步 · 自组织成 SU(5) 基态：基态同步&quot;">​</a></h3><p>但<strong>可能性还不是物理</strong>。GL(5) 的自守谱要经过<strong>同步算符的紧化</strong>，才被锁定为 SU(5) 基态。这一步的状态是<strong>基态同步</strong>。【锚 A-12】【锚 A-13】</p><p>用原文的写法，这是整个链条最凝练的一句：</p><p>$$\\text{GL(5) 潜能}\\ \\xrightarrow{\\ \\text{同步算符}\\ }\\ \\text{SU(5) 现实}$$</p><p>非紧的约化群 $\\mathrm{GL}(5)$ 是潜能，紧的物理群 $\\mathrm{SU}(5)$（及其 $U(1)$ 因子）是现实，而紧化映射 $\\hat{\\mathcal S}<em>0:\\mathcal H</em>{\\text{auto}}(\\mathrm{GL}(5))\\to\\mathcal H_{\\text{phys}}(SU(5))$ 就是潜能现实化的机制。【锚 A-13】</p><blockquote><p><strong>一个必须就地说明的层级选择</strong>：为什么固定在 GL(5)？因为<strong>基态是未分化的统一体</strong>——SU(5) 是完整时空（四维 Regge 几何 + 规范结构尚未分离），而重组实现直接输出 $U(1)\\times SU(2)\\times SU(3)$，并不与 GL(n) 层级挂钩。所以顺序是：<strong>先有统一的基态，后有重组实现的规范群</strong>。这也解释了为什么 SU(5) 的地位：它是含标准模型的最小单群（$\\operatorname{rank}SU(5)=4=\\operatorname{rank}(U(1)\\times SU(2)\\times SU(3))$），而 $S_5=\\mathrm{Weyl}(A_4)$ 在原文中只作<strong>与四维 Regge 几何自洽的交叉印证，不作为推导</strong>。【锚 A-14】</p></blockquote><h3 id="第五步-·-p-进大小耦合分化-重组实现" tabindex="-1">第五步 · p 进大小耦合分化／重组实现 <a class="header-anchor" href="#第五步-·-p-进大小耦合分化-重组实现" aria-label="Permalink to &quot;第五步 · p 进大小耦合分化／重组实现&quot;">​</a></h3><p>分化机制被表述为：<strong>p 进大小耦合层级 = 嘉当矩阵分化</strong>，状态是<strong>重组实现</strong>。【锚 A-12】</p><blockquote><p><strong>断点（就地标出）</strong>：这一步由<strong>中子缺陷驱动</strong>，而中子缺陷矩阵的四个缺口 <strong>N1–N4</strong> 状态为 <code>待证明</code>；FG 角亏一侧（N4）对应 <code>FGChain/</code>，其 12 个模块中多数不通过。<strong>在本稿中，第五步之后的一切陈述都应以&quot;N1–N4 未闭合&quot;为前提来读。</strong> 另据集成理论结论部分的审计，<strong>几何耦合 $\\beta$ 的第一性来源</strong>与<strong>中子缺陷 $\\delta$</strong> 同属关键未闭合处。【锚 A-19】</p></blockquote><h3 id="第六步-·-u-1-times-su-2-times-su-3-物理现实" tabindex="-1">第六步 · $U(1)\\times SU(2)\\times SU(3)$：物理现实 <a class="header-anchor" href="#第六步-·-u-1-times-su-2-times-su-3-物理现实" aria-label="Permalink to &quot;第六步 · $U(1)\\times SU(2)\\times SU(3)$：物理现实&quot;">​</a></h3><p>链条的终点是标准模型规范群，状态是<strong>物理现实</strong>——并且原文特别注明：它是<strong>重组实现的直接输出</strong>，不与 GL(n) 层级挂钩。【锚 A-12】</p><h3 id="_3-7-链条的可观测边界" tabindex="-1">3.7 链条的可观测边界 <a class="header-anchor" href="#_3-7-链条的可观测边界" aria-label="Permalink to &quot;3.7 链条的可观测边界&quot;">​</a></h3><p>链条到这里是完整的，但<strong>能看到的</strong>比<strong>存在的</strong>少。原文把这件事分成三句话：</p><ul><li><strong>本体论上</strong>：CQM 与朗兰兹纲领相关；</li><li><strong>认识论上</strong>：CQM 固定在 GL(5) 层级计算；</li><li><strong>物理上</strong>：观测受禁闭与能标锁死限制。【锚 A-16】</li></ul><p>它的哲学命题是：<strong>前时空与 FG 与朗兰兹纲领相关，GR 是否相关不确定</strong>——并且强调是&quot;相关&quot;而非&quot;独占&quot;。原因也写在原文里：一旦退相干，非紧的 GL(5) 就被紧化成物理的 SU(5)，朗兰兹纲领的原始结构就<strong>看不见</strong>了。【锚 A-15】</p><hr><h2 id="第四章-第二根链条-量纲是怎么长出来的-链条层" tabindex="-1">第四章 第二根链条：量纲是怎么长出来的（链条层） <a class="header-anchor" href="#第四章-第二根链条-量纲是怎么长出来的-链条层" aria-label="Permalink to &quot;第四章 第二根链条：量纲是怎么长出来的（链条层）&quot;">​</a></h2><p>前一根链条回答&quot;对称性从哪来&quot;，这一根回答&quot;量纲从哪来&quot;。它的形式同样是一条链，但操作单位是<strong>特征常数</strong>。</p><h3 id="_4-1-总原则-每压掉一个量纲-冒出一个特征常数" tabindex="-1">4.1 总原则：每压掉一个量纲，冒出一个特征常数 <a class="header-anchor" href="#_4-1-总原则-每压掉一个量纲-冒出一个特征常数" aria-label="Permalink to &quot;4.1 总原则：每压掉一个量纲，冒出一个特征常数&quot;">​</a></h3><p>量纲不是预先给定的坐标系，而是<strong>发生学层级</strong>：从第一个量纲开始，每往下一层&quot;压掉&quot;一个量纲，就有一个特征常数冒出来承担转换。原文的统一公式模式因此写成：</p><p>$$\\text{旧量纲}\\times\\text{特征常数}=\\text{新量纲}\\qquad(\\text{新旧指发生学先后}).$$</p><p>沿链条出现的常数族记作 $K$ 下标：$K_L,K_M,K_Q,K_\\Theta,K_N,K_J$。【锚 A-17】</p><h3 id="_4-2-链条的两端与两处细节" tabindex="-1">4.2 链条的两端与两处细节 <a class="header-anchor" href="#_4-2-链条的两端与两处细节" aria-label="Permalink to &quot;4.2 链条的两端与两处细节&quot;">​</a></h3><ul><li><strong>时间 $T$</strong> 是<strong>第一个量纲</strong>；无量纲→时间的特征常数<strong>未知</strong>（原文的表述是&quot;可能没有&quot;）。</li><li><strong>长度 $L$</strong> 由 $K_L$ 生成：$r_{\\text{coupling}}\\cdot K_L=r_{\\text{phys}}$，其中 $K_L$ 是<strong>禁闭映射常数</strong>；$r_{\\text{coupling}}$ 与固有时共轭。</li><li><strong>质量 $M$</strong> 由 $K_M$ 生成，而 $K_M=G_N^{-1}$。</li><li><strong>电荷 $Q$</strong> 由 $K_Q$ 生成；温度、物质的量、发光强度各自有对应位置。</li><li><strong>光速 $c$</strong> 的地位需要单独说：它是<strong>时空同步前沿速度</strong>，<strong>不承担量纲转换</strong>。【锚 A-17】</li></ul><h3 id="_4-3-一个容易被读错的先后关系" tabindex="-1">4.3 一个容易被读错的先后关系 <a class="header-anchor" href="#_4-3-一个容易被读错的先后关系" aria-label="Permalink to &quot;4.3 一个容易被读错的先后关系&quot;">​</a></h3><p>链条上时间在前、长度在后，但<strong>先后不等于依托</strong>：长度并不经由时间生成——时间来自事件计数，长度来自耦合空间经 $K_L$（§6.3.1）。二者随后<strong>同步</strong>为时空，其表现是保持时空间隔的群 $O(1,3)$ 与光速 $c$。原文对这一区的措辞是&quot;两个锚点、各自自无量纲来源、各自自守化&quot;。【锚 A-17】</p><h3 id="_4-4-断点与数值状态" tabindex="-1">4.4 断点与数值状态 <a class="header-anchor" href="#_4-4-断点与数值状态" aria-label="Permalink to &quot;4.4 断点与数值状态&quot;">​</a></h3><ul><li><strong>$K_L$ 值有待确定</strong>：这是原文的措辞，不是本稿的谨慎。因此凡出现 $K_L$ 的数值讨论，都必须携带这一状态。</li><li>原文内部对 $K_L$ 给出了<strong>多条值链</strong>（例如 0.656 与 0.67860 等，分属不同情境与几何标定），这是<strong>并列登记</strong>的写法；本稿不替它挑一条。</li><li>量纲层的更细口径（温度、物质的量等的位置与理由）以 <code>01 核心理论/CQM_核心_量纲与群论.md</code> 的 §5、§6.5 为权威，本稿不复述以免与原文分叉。【锚 A-17】</li></ul><hr><h2 id="第五章-两条引力与它们的前提-链条层" tabindex="-1">第五章 两条引力与它们的前提（链条层） <a class="header-anchor" href="#第五章-两条引力与它们的前提-链条层" aria-label="Permalink to &quot;第五章 两条引力与它们的前提（链条层）&quot;">​</a></h2><h3 id="_5-1-前时空-先于引力" tabindex="-1">5.1 前时空：先于引力 <a class="header-anchor" href="#_5-1-前时空-先于引力" aria-label="Permalink to &quot;5.1 前时空：先于引力&quot;">​</a></h3><p>在 CQM 里，<strong>引力只有两种：GR 与 FG</strong>；而两者都以前时空为前层——<strong>前时空先于引力</strong>（它不属引力）。分层读法是：前时空（先于引力）→ GR（平庸因果网络 = 时空）→ FG（非平庸因果网络 = 纤维丛）。【锚 A-18】</p><p><strong>断点（就地标出）</strong>：FG 一侧与角亏/中子缺陷相关的 N4 状态为 <code>待证明</code>，其形式化载体 <code>FGChain/</code> 多数模块不通过。【锚 A-19】</p><h3 id="_5-2-与退相干的关系" tabindex="-1">5.2 与退相干的关系 <a class="header-anchor" href="#_5-2-与退相干的关系" aria-label="Permalink to &quot;5.2 与退相干的关系&quot;">​</a></h3><p>引力提供退相干赖以发生的因果结构；但退相干不等于只由引力承担（见第一章）。本稿把它放在这里，是因为&quot;两种引力&quot;与&quot;退相干&quot;在链条上挨着，容易被读成同一件事的两面——原文并不主张这一点。【锚 A-04】</p><hr><h2 id="第六章-断点-未闭合的地方留在链条上" tabindex="-1">第六章 断点：未闭合的地方留在链条上 <a class="header-anchor" href="#第六章-断点-未闭合的地方留在链条上" aria-label="Permalink to &quot;第六章 断点：未闭合的地方留在链条上&quot;">​</a></h2><p>链条不是无缺口的通路。把缺口写进正文，而不是收进附录，是本稿最想立住的一件事。下表逐字取自缺口台账的编号与状态：</p><table tabindex="0"><thead><tr><th style="text-align:left;">编号范围</th><th style="text-align:left;">主题</th><th style="text-align:left;">状态</th><th style="text-align:left;">影响链条的哪一段</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>C</strong></td><td style="text-align:left;">核心存在性缺口</td><td style="text-align:left;"><code>axiom</code></td><td style="text-align:left;">全链条（原文称其为严谨性最大敞口）</td></tr><tr><td style="text-align:left;"><strong>G2–G8</strong></td><td style="text-align:left;">核心理论缺口</td><td style="text-align:left;"><code>待证明</code>（G6 未定义／占位）</td><td style="text-align:left;">第二至第四章的核心构造</td></tr><tr><td style="text-align:left;"><strong>G9–G22</strong></td><td style="text-align:left;">超导涌现链</td><td style="text-align:left;">14 项，<code>待证明</code>／部分已闭合</td><td style="text-align:left;">本稿未展开的分支（第五分册起）</td></tr><tr><td style="text-align:left;"><strong>N1–N4</strong></td><td style="text-align:left;">中子缺陷矩阵与 FG 角亏</td><td style="text-align:left;"><code>待证明</code></td><td style="text-align:left;">第三章第五步、第五章</td></tr><tr><td style="text-align:left;"><strong>H3.1–H3.3</strong></td><td style="text-align:left;">层级假设</td><td style="text-align:left;"><code>axiom</code></td><td style="text-align:left;">第三章的层级选择</td></tr><tr><td style="text-align:left;">黎曼 / Mathieu / 素数冻结 / Tate 自对偶 / $G_N$ 变分</td><td style="text-align:left;">见台账</td><td style="text-align:left;"><code>猜想</code>／<code>数值验证</code>／<code>axiom</code></td><td style="text-align:left;">第二章 $☯$ 的谱表示、第七章数值</td></tr></tbody></table><p>【锚 A-19】</p><p>台账自带三条联动规则，本稿照办：①标&quot;已证明&quot;的项，对应模块不得报出 <code>axiom</code>；②缺口闭合须同时更新台账状态列与 Lean 模块；③<strong>不得</strong>把&quot;未解决／待证明&quot;改写为&quot;已解决&quot;而不提供证明。</p><hr><h2 id="第七章-数值的地位-推导、构造后验、实验参数-要分开写" tabindex="-1">第七章 数值的地位：推导、构造后验、实验参数，要分开写 <a class="header-anchor" href="#第七章-数值的地位-推导、构造后验、实验参数-要分开写" aria-label="Permalink to &quot;第七章 数值的地位：推导、构造后验、实验参数，要分开写&quot;">​</a></h2><p>同一页里出现的三个数，严格性完全不同，混在一起写就等于欺骗。按原文标注：</p><table tabindex="0"><thead><tr><th style="text-align:left;">量</th><th style="text-align:left;">写法</th><th style="text-align:left;">地位</th></tr></thead><tbody><tr><td style="text-align:left;">$☯$</td><td style="text-align:left;">$\\approx 0.02309570897$</td><td style="text-align:left;">由 $\\xi$ <strong>严格推出</strong>，解析值与数值微分互验至 $10^{-7}$【锚 A-07】</td></tr><tr><td style="text-align:left;">$\\alpha^{-1}$</td><td style="text-align:left;">$16384\\pi/375 \\approx 137.2583$</td><td style="text-align:left;">由 4-单纯形边-面关联矩阵 $M=E^TE$ 的本征值 ${9,4,1}$（经 $S_5$ 表示论）锁定三种规范耦合的相对强度；与 CODATA 2022 值偏差约 <strong>0.162%</strong>（≈1622 ppm），原文定位为<strong>一阶近似、待高阶修正</strong>，并明言<strong>不能称&quot;严格/精确&quot;</strong>；另有 Wyler 口径 $\\frac{16}{9}\\pi^{11/4}(5!)^{1/4}\\approx137.0361$（偏差 0.61 ppm，由 $A_4$ 全部群论不变量给出），两条口径<strong>并列登记</strong>，且原文注明两者偏差 ppm 之比约 2659 &quot;是相对精度之比，不构成独立精度证据&quot;【锚 A-20】</td></tr><tr><td style="text-align:left;">$G_N$</td><td style="text-align:left;">与 CODATA 偏差约 $-3$ ppm</td><td style="text-align:left;"><strong>构造后验数字校验，待独立复现</strong>；原文同时写明：以纯数学&quot;推导&quot;物理常数的主张，目前未被主流学界当作公认的独立第一性推导【锚 A-20】【锚 A-17】</td></tr></tbody></table><p>最后一行是全稿最容易写坏的地方。正确的写法是保留完整的限定语，而不是把&quot;偏差 −3 ppm&quot;从&quot;构造后验数字校验，待独立复现&quot;里摘出来单独说——摘出来读，它就会变成一个已经成立的结论。本稿不那样写。</p><hr><h2 id="附录-a-·-锚点表" tabindex="-1">附录 A · 锚点表 <a class="header-anchor" href="#附录-a-·-锚点表" aria-label="Permalink to &quot;附录 A · 锚点表&quot;">​</a></h2><p><strong>核对状态</strong>含义：<code>逐字核对</code>＝本次撰写时已在原文该处逐字读过并引用；<code>待逐字核对</code>＝定位来自根 <code>README.md</code> 的索引行，尚未回到原文逐字校对。</p><table tabindex="0"><thead><tr><th style="text-align:left;">锚</th><th style="text-align:left;">论断摘要</th><th style="text-align:left;">出处</th><th style="text-align:left;">定位</th><th style="text-align:left;">核对状态</th></tr></thead><tbody><tr><td style="text-align:left;">A-01</td><td style="text-align:left;">三条既有进路的困难与&quot;量子化耦合常数本身&quot;的转向</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_集成理论.md</code></td><td style="text-align:left;">§3.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-02</td><td style="text-align:left;">物质先在（L0）</td><td style="text-align:left;">同上</td><td style="text-align:left;">§1.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-03</td><td style="text-align:left;">存在先于过程，过程维持存在</td><td style="text-align:left;">同上</td><td style="text-align:left;">§1.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-04</td><td style="text-align:left;">退相干是子类自组织的表现；引力提供因果结构但不独占退相干</td><td style="text-align:left;">同上</td><td style="text-align:left;">摘要「退相干是子类自组织的表现」注</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-05</td><td style="text-align:left;">不用 $r$ 的理由与取 $u=\\ln r$ 的三点收益、RG 对数跑动</td><td style="text-align:left;">同上</td><td style="text-align:left;">§3.2</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-06</td><td style="text-align:left;">$[\\hat u,\\hat p_u]=i$；$\\hat p_u=\\hat v_\\tau/☯$；不确定性关系的物理诠释</td><td style="text-align:left;">同上</td><td style="text-align:left;">§3.3</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-07</td><td style="text-align:left;">$☯$ 的解析式、数值与互验精度</td><td style="text-align:left;">同上</td><td style="text-align:left;">§3.4</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-08</td><td style="text-align:left;">Hadamard 恒等式（不依赖 RH）与谱表示（条件于 RH）</td><td style="text-align:left;">同上</td><td style="text-align:left;">§3.4.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-09</td><td style="text-align:left;">为什么取 $\\xi$ 而非 $\\zeta$（零点集与极点）</td><td style="text-align:left;">同上</td><td style="text-align:left;">§3.4.2</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-10</td><td style="text-align:left;">Sprinkling 测度 $d\\mu=e^{-u}du$ 及证明</td><td style="text-align:left;">同上</td><td style="text-align:left;">§4.1 定理 4.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-11</td><td style="text-align:left;">同构对照表与&quot;不是类比而是严格同构&quot;</td><td style="text-align:left;">同上</td><td style="text-align:left;">§4.2</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-12</td><td style="text-align:left;">发生学六步链条与每步的本体论状态</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_朗兰兹分层共振与相变量子.md</code></td><td style="text-align:left;">§0.1、§0.2</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-13</td><td style="text-align:left;">GL(5) 潜能先在、SU(5) 后成；紧化映射 $\\hat{\\mathcal S}_0$</td><td style="text-align:left;">同上</td><td style="text-align:left;">§0.3</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-14</td><td style="text-align:left;">为什么固定 GL(5)；SU(5) 的最小单群地位；$S_5$ 只作交叉印证</td><td style="text-align:left;">同上</td><td style="text-align:left;">§0.4</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-15</td><td style="text-align:left;">前时空与 FG 与朗兰兹纲领相关、GR 不确定；退相干后原始结构不可见</td><td style="text-align:left;">同上</td><td style="text-align:left;">§0.5</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-16</td><td style="text-align:left;">本体论完整、认识论受限的可计算边界</td><td style="text-align:left;">同上</td><td style="text-align:left;">§0.6</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-17</td><td style="text-align:left;">量纲发生学层级、$K$ 家族、统一公式模式、$c$ 的地位、$K_L$ 值待定</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code></td><td style="text-align:left;">§六（细口径见 §5、§6.5）</td><td style="text-align:left;">待逐字核对</td></tr><tr><td style="text-align:left;">A-18</td><td style="text-align:left;">引力只有两种（GR/FG）；前时空先于引力、不属引力</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_引力存在论前提.md</code></td><td style="text-align:left;">§一</td><td style="text-align:left;">待逐字核对</td></tr><tr><td style="text-align:left;">A-19</td><td style="text-align:left;">缺口编号、状态、Lean 对应与联动规则</td><td style="text-align:left;"><code>一体化研究/附录/缺口台账.md</code></td><td style="text-align:left;">§一、§二、§五</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-20</td><td style="text-align:left;">$\\alpha^{-1}=16384\\pi/375$、$G_N$ 与 CODATA 偏差约 −3 ppm 及其限定语</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_集成理论.md</code></td><td style="text-align:left;">摘要第（4）条</td><td style="text-align:left;">逐字核对</td></tr></tbody></table><h2 id="附录-b-·-撰写准则-每条论断要过六关" tabindex="-1">附录 B · 撰写准则（每条论断要过六关） <a class="header-anchor" href="#附录-b-·-撰写准则-每条论断要过六关" aria-label="Permalink to &quot;附录 B · 撰写准则（每条论断要过六关）&quot;">​</a></h2><p>写作不是&quot;读过就能写&quot;。参照文献计量与信息检索领域对<strong>引文保真</strong>（citation fidelity）的通行分层，本稿的自检顺序是：</p><ol><li><strong>出处存在</strong>——文档在该位置存在；</li><li><strong>对象正确</strong>——引的是这一篇、这一节，不是同名邻节；</li><li><strong>段落相关</strong>——该处确实谈这件事；</li><li><strong>论断被支撑</strong>——从该段能推出本稿所写的这句话；</li><li><strong>限定语保留</strong>——范围、条件、不确定性不得在转写中丢失（$☯$ 的&quot;条件于 RH&quot;、$G_N$ 的&quot;构造后验数字校验，待独立复现&quot;、$K_L$ 的&quot;值有待确定&quot;都属于此关）；</li><li><strong>来源适配</strong>——该论断只由权威处承担，不由本稿或索引行承担。</li></ol><p>其中第 5 关是本稿失守风险最高的一关，也是&quot;看起来写得更顺&quot;与&quot;写得更准&quot;分道扬镳的地方：把限定语去掉，句子会立刻变漂亮。本稿的选择是留下它们。</p><h2 id="附录-c-·-后续分册-待续" tabindex="-1">附录 C · 后续分册（待续） <a class="header-anchor" href="#附录-c-·-后续分册-待续" aria-label="Permalink to &quot;附录 C · 后续分册（待续）&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">分册</th><th style="text-align:left;">覆盖链条段</th><th style="text-align:left;">主要依据</th></tr></thead><tbody><tr><td style="text-align:left;">第二分册</td><td style="text-align:left;">SU(5) 涌现与谱结构（4-单纯形本征值 ${9,4,1}$、$\\alpha^{-1}$ 的来源）</td><td style="text-align:left;"><code>集成理论</code> 第七部分</td></tr><tr><td style="text-align:left;">第三分册</td><td style="text-align:left;">谱方程与黎曼零点（Sierra-CQM 耦谱定理）</td><td style="text-align:left;"><code>集成理论</code> 第八部分</td></tr><tr><td style="text-align:left;">第四分册</td><td style="text-align:left;">超导涌现链（跃迁耦级谱 $2\\ln n$、自由能竞争与 $T_c$），含 G9–G22 断点</td><td style="text-align:left;"><code>集成理论</code> 第十一部分、<code>CQM_超导_专题与扩展.md</code> §13</td></tr><tr><td style="text-align:left;">第五分册</td><td style="text-align:left;">与标准理论的关系、纤维丛结构与涨落伴丛</td><td style="text-align:left;"><code>集成理论</code> 第十二、十三部分</td></tr><tr><td style="text-align:left;">第六分册</td><td style="text-align:left;">量纲发生学专章（$K$ 家族逐项、自守形式猜想）</td><td style="text-align:left;"><code>量纲与群论</code> §六、§七</td></tr></tbody></table><p>每一分册写完即接阅读站：链条层进导航，技术层挂原文链接（阅读站已具备术语卡与展开链页，分册正文将以同样的锚点方式接入）。</p></div>',1)])])}const f=e(d,[["render",r]]);export{h as __pageData,f as default};
